function f = HS40_f(x)
f = -x(1).*x(2).*x(3).*x(4);
end

function g = HS40_g(x)
g = zeros(4, 1);
g(1) = -x(2).*x(3).*x(4);
g(2) = -x(1).*x(3).*x(4);
g(3) = -x(1).*x(2).*x(4);
g(4) = -x(1).*x(2).*x(3);
end

function c = HS40_c(x)
c = zeros(3, 1);
c(1) = x(1).^3 + x(2).^2 - 1;
c(2) = x(1).^2.*x(4) - x(3);
c(3) = -x(2) + x(4).^2;
end

function J = HS40_J(x)
J = zeros(3, 4);
J(1, 1) = 3*x(1).^2;
J(1, 2) = 2*x(2);
J(2, 1) = 2*x(1).*x(4);
J(2, 3) = -1;
J(2, 4) = x(1).^2;
J(3, 2) = -1;
J(3, 4) = 2*x(4);
end
